alter table public.areas add column if not exists area_m2 numeric not null default 0; alter table public.areas drop constraint if exists areas_area_m2_check; alter table public.areas add constraint areas_area_m2_check check (area_m2 >= 0); create or replace function public.recalculate_project_building_weights(p_project_id uuid) returns void language plpgsql security definer set search_path = public as $$ declare v_total numeric; begin select coalesce(sum(area_m2), 0) into v_total from public.areas a join public.buildings b on b.id = a.building_id where b.project_id = p_project_id; update public.buildings b set weight_percent = case when v_total > 0 then round((coalesce((select sum(a.area_m2) from public.areas a where a.building_id = b.id), 0) / v_total) * 100, 2) else 0 end where b.project_id = p_project_id; end; $$; create or replace function public.recalculate_weights_after_area_change() returns trigger language plpgsql security definer set search_path = public as $$ begin if tg_op = 'DELETE' then perform public.recalculate_project_building_weights((select project_id from public.buildings where id = old.building_id)); return old; end if; perform public.recalculate_project_building_weights((select project_id from public.buildings where id = new.building_id)); if tg_op = 'UPDATE' and old.building_id <> new.building_id then perform public.recalculate_project_building_weights((select project_id from public.buildings where id = old.building_id)); end if; return new; end; $$; drop trigger if exists areas_recalculate_building_weights on public.areas; create trigger areas_recalculate_building_weights after insert or update of area_m2, building_id or delete on public.areas for each row execute function public.recalculate_weights_after_area_change();
